[Extensionof(tableStr(VendInvoiceJour))]
final class METVendInvoiceJour_T_Extension
{

    /// <summary>
    /// The code neis replacing the source document header value to -1 when the value is 0 
    /// because the find method in the table is using the source document header as a parameter and when the value is 0 it is not finding any record, 
    /// but when we replace it with -1 it is finding the record with source document header 0. 
    /// This is a workaround to avoid changing the find method in the table which might be used in other places and we don't want to affect those places.
    /// </summary>
    /// <param name = "_sourceDocumentHeader"></param>
    /// <param name = "_forUpdate"></param>
    /// <returns></returns>   
    /// TODO: This is a bug in Microsoft code when Date of VAT Register featuce key is turned on and was causing performance issue during purchase order confrimation processing
    /// The below code should be removed once the bug is fixed by Microsoft.

}

Method.Source:
public static VendInvoiceJour findSourceDocumentHeader(SourceDocumentHeaderRecId _sourceDocumentHeader,boolean _forUpdate)
{
    VendInvoiceJour vendInvoiceJour;
    if(_sourceDocumentHeader == 0)
    {
        _sourceDocumentHeader = -1;
    }
    vendInvoiceJour = next findSourceDocumentHeader(_sourceDocumentHeader, _forUpdate);

    return vendInvoiceJour;
}
